import os
import boto3
import json

def get_model_output_with_metadata(prompt: str) -> dict:
    """
    Invokes a model on Amazon Bedrock and returns its output along with usage metadata.
    """
    # Initialize the Bedrock client
    # AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY should be set as environment variables
    # or configured via AWS CLI.
    # The region name should be where your Bedrock model is available.
    bedrock_runtime = boto3.client(
        service_name='bedrock-runtime',
        region_name=os.getenv('AWS_REGION_NAME', 'us-east-1')
    )

    # The model ID for Anthropic Claude 3 Sonnet
    # For a list of available models and their IDs:
    # https://docs.aws.amazon.com/bedrock/latest/userguide/model-ids.html
    model_id = 'anthropic.claude-3-sonnet-20240229-v1:0'
    content_type = 'application/json'
    accept = 'application/json'

    # Construct the body for Claude 3 model
    body = json.dumps({
        "messages": [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt}
                ]
            }
        ],
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": 100,
        "temperature": 0.5
    })

    response = bedrock_runtime.invoke_model_with_response_stream(
        body=body,
        modelId=model_id,
        contentType=content_type,
        accept=accept
    )

    # Process the streamed response to get the full output and metadata
    model_output = ""
    input_tokens = 0
    output_tokens = 0

    for event in response['body']:
        chunk = event.get('chunk')
        if chunk:
            chunk_obj = json.loads(chunk['bytes'].decode('utf-8'))
            if chunk_obj['type'] == 'content_block_delta':
                model_output += chunk_obj['delta']['text']
            elif chunk_obj['type'] == 'message_start':
                # Message start contains initial metadata like role
                pass
            elif chunk_obj['type'] == 'message_stop':
                # Message stop contains usage information
                usage = chunk_obj.get('usage', {})
                input_tokens = usage.get('input_tokens', 0)
                output_tokens = usage.get('output_tokens', 0)
            elif chunk_obj['type'] == 'message_delta':
                # For non-streaming, message_delta would contain model output.
                # For streaming, content_block_delta provides text.
                pass
            elif chunk_obj['type'] == 'content_block_start':
                pass # Initial metadata for a content block
            elif chunk_obj['type'] == 'content_block_stop':
                pass # End of a content block


    metadata = {
        "provider": "Amazon Bedrock",
        "model_id": model_id,
        "usage": {
            "input_tokens": input_tokens,
            "output_tokens": output_tokens,
            "total_tokens": input_tokens + output_tokens
        }
    }

    return {
        "generated_text": model_output.strip(),
        "metadata": metadata
    }
